function spring(x0, y0, x1, y1, coils) {
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  for (var i = 1; i < coils; i++) {
    var f = i / coils;
    var sx = x0 + (x1 - x0) * f;
    var sy = y0 + (y1 - y0) * f + (i % 2 === 0 ? -7 : 7);
    ctx.lineTo(sx, sy);
  }
  ctx.lineTo(x1, y1);
  ctx.stroke();
}

ctx.lineWidth = 2;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var wallW = 7;
var left = 30, right = W - 30;
var cartW = 30, cartH = 24;
var eq1 = left + (right - left) * 0.34;
var eq2 = left + (right - left) * 0.66;
var d = Math.min(20, (right - left) * 0.05);

var rows = [
  { y: H * 0.30, s1: 1, s2: 1, name: "In-phase mode", sub: "middle spring keeps its natural length" },
  { y: H * 0.72, s1: -1, s2: 1, name: "Antiphase mode", sub: "middle spring stretched by twice the displacement" }
];

for (var r = 0; r < rows.length; r++) {
  var row = rows[r];
  var y = row.y;
  var x1 = eq1 + row.s1 * d;
  var x2 = eq2 + row.s2 * d;

  ctx.fillStyle = C.faint;
  ctx.fillRect(left - wallW, y - 30, wallW, 60);
  ctx.fillRect(right, y - 30, wallW, 60);

  ctx.strokeStyle = C.accent;
  spring(left, y, x1 - cartW / 2, y, 10);
  spring(x2 + cartW / 2, y, right, y, 10);

  ctx.strokeStyle = (row.s1 === row.s2) ? C.rule : C.accent;
  ctx.lineWidth = (row.s1 === row.s2) ? 1.5 : 2.5;
  spring(x1 + cartW / 2, y, x2 - cartW / 2, y, 8);
  ctx.lineWidth = 2;

  ctx.strokeStyle = C.rule;
  ctx.setLineDash([3, 4]);
  ctx.beginPath(); ctx.moveTo(eq1, y - 34); ctx.lineTo(eq1, y + 26); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(eq2, y - 34); ctx.lineTo(eq2, y + 26); ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle = C.figure;
  ctx.fillRect(x1 - cartW / 2, y - cartH / 2, cartW, cartH);
  ctx.fillRect(x2 - cartW / 2, y - cartH / 2, cartW, cartH);

  ctx.fillStyle = C.paper;
  ctx.textAlign = "center";
  ctx.fillText("1", x1, y + 4);
  ctx.fillText("2", x2, y + 4);

  ctx.strokeStyle = C.ink;
  ctx.fillStyle = C.ink;
  for (var q = 0; q < 2; q++) {
    var cx = q === 0 ? x1 : x2;
    var sgn = q === 0 ? row.s1 : row.s2;
    var ay = y - cartH / 2 - 9;
    ctx.beginPath();
    ctx.moveTo(cx, ay);
    ctx.lineTo(cx + sgn * 22, ay);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(cx + sgn * 22, ay);
    ctx.lineTo(cx + sgn * 15, ay - 4);
    ctx.lineTo(cx + sgn * 15, ay + 4);
    ctx.closePath();
    ctx.fill();
  }

  ctx.fillStyle = C.ink;
  ctx.textAlign = "left";
  ctx.fillText(row.name, left, y - 42);
  ctx.fillStyle = C.faint;
  ctx.fillText(row.sub, left, y + 44);
}

ctx.textAlign = "right";
ctx.fillStyle = C.ink;
ctx.fillText("omega = sqrt(k/m)", right, H * 0.30 - 42);
ctx.fillText("omega = sqrt((k+2kc)/m)", right, H * 0.72 - 42);
ctx.textAlign = "left";

function spring(x0, y0, x1, y1, coils) {
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  for (var i = 1; i < coils; i++) {
    var f = i / coils;
    var sx = x0 + (x1 - x0) * f;
    var sy = y0 + (y1 - y0) * f + (i % 2 === 0 ? -7 : 7);
    ctx.lineTo(sx, sy);
  }
  ctx.lineTo(x1, y1);
  ctx.stroke();
}

ctx.lineWidth = 2;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var m = 0.5, k = 200;
var k2 = k * (1 + p.detune / 100);
var c = p.kc / m;
var a = (k + p.kc) / m;
var b = (k2 + p.kc) / m;
var half = (a - b) / 2;
var mean = (a + b) / 2;
var root = Math.sqrt(half * half + c * c);
var lamLo = mean - root, lamHi = mean + root;
var wLo = Math.sqrt(lamLo), wHi = Math.sqrt(lamHi);

// eigenvectors of [[a,-c],[-c,b]]
function vec(lam) {
  var vx = c, vy = a - lam;
  var n = Math.sqrt(vx * vx + vy * vy);
  return [vx / n, vy / n];
}
var e1 = vec(lamLo), e2 = vec(lamHi);
// decompose initial (1,0)
var det = e1[0] * e2[1] - e1[1] * e2[0];
var al = (1 * e2[1] - 0 * e2[0]) / det;
var be = (e1[0] * 0 - e1[1] * 1) / det;

var ts = t * 1.2;
function pos(tt) {
  var u = al * Math.cos(wLo * tt);
  var v = be * Math.cos(wHi * tt);
  return [u * e1[0] + v * e2[0], u * e1[1] + v * e2[1]];
}
var now = pos(ts);

var wallW = 7;
var left = 30, right = W - 30;
var cartW = 28, cartH = 22;
var eq1 = left + (right - left) * 0.34;
var eq2 = left + (right - left) * 0.66;
var y = H * 0.26;
var amp = Math.min(24, (right - left) * 0.055);
var x1 = eq1 + now[0] * amp;
var x2 = eq2 + now[1] * amp;

ctx.fillStyle = C.faint;
ctx.fillRect(left - wallW, y - 26, wallW, 52);
ctx.fillRect(right, y - 26, wallW, 52);

ctx.strokeStyle = C.accent;
spring(left, y, x1 - cartW / 2, y, 10);
spring(x2 + cartW / 2, y, right, y, 10);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
spring(x1 + cartW / 2, y, x2 - cartW / 2, y, 8);
ctx.lineWidth = 2;

ctx.fillStyle = C.figure;
ctx.fillRect(x1 - cartW / 2, y - cartH / 2, cartW, cartH);
ctx.fillStyle = C.accent;
ctx.fillRect(x2 - cartW / 2, y - cartH / 2, cartW, cartH);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("cart 1", eq1, y + 34);
ctx.fillText("cart 2", eq2, y + 34);
ctx.textAlign = "left";

// traces
var gy = H * 0.72;
var span = W - 2 * left;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(left, gy); ctx.lineTo(left + span, gy); ctx.stroke();

var winSec = 14;
var hgt = Math.min(30, H * 0.16);
for (var s = 0; s < 2; s++) {
  ctx.strokeStyle = s === 0 ? C.figure : C.accent;
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  for (var i = 0; i <= 300; i++) {
    var tt = ts - winSec + winSec * i / 300;
    if (tt < 0) tt = 0;
    var pp = pos(tt);
    var px = left + span * i / 300;
    var py = gy - pp[s] * hgt;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.stroke();
}
ctx.fillStyle = C.ink;
ctx.fillText("displacement against time: cart 1 dark, cart 2 accent", left, gy + hgt + 16);

var dw = wHi - wLo;
var frac = c * c / (c * c + half * half);
out.note = "modes " + wLo.toFixed(2) + " and " + wHi.toFixed(2) + " rad/s, beat period " +
  (2 * Math.PI / dw).toFixed(2) + " s, max energy transferred " + (100 * frac).toFixed(0) + "%";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

var k = 200, m = 0.5;
var N = Math.round(p.N);
var n = Math.round(p.mode);
if (n > N) n = N;
var w = 2 * Math.sqrt(k / m) * Math.sin(n * Math.PI / (2 * (N + 1)));

var left = 34, right = W - 34;
var span = right - left;
var gap = span / (N + 1);
var y = H * 0.34;
var amp = Math.min(gap * 0.35, 22);
var phase = Math.cos(w * t * 0.18);

// walls
ctx.fillStyle = C.faint;
ctx.fillRect(left - 7, y - 26, 7, 52);
ctx.fillRect(right, y - 26, 7, 52);

// equilibrium ticks
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 4]);
for (var i = 1; i <= N; i++) {
  var ex = left + gap * i;
  ctx.beginPath(); ctx.moveTo(ex, y - 22); ctx.lineTo(ex, y + 22); ctx.stroke();
}
ctx.setLineDash([]);

// springs and beads
var xs = [left];
for (var i = 1; i <= N; i++) {
  var shape = Math.sin(n * Math.PI * i / (N + 1));
  xs.push(left + gap * i + shape * amp * phase);
}
xs.push(right);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.6;
for (var s = 0; s < xs.length - 1; s++) {
  ctx.beginPath();
  ctx.moveTo(xs[s], y);
  for (var q = 1; q < 8; q++) {
    var f = q / 8;
    ctx.lineTo(xs[s] + (xs[s + 1] - xs[s]) * f, y + (q % 2 === 0 ? -6 : 6));
  }
  ctx.lineTo(xs[s + 1], y);
  ctx.stroke();
}
ctx.fillStyle = C.figure;
for (var i = 1; i <= N; i++) {
  ctx.beginPath();
  ctx.arc(xs[i], y, 8, 0, Math.PI * 2);
  ctx.fill();
}

// mode shape curve
var cy = H * 0.78;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(left, cy); ctx.lineTo(right, cy); ctx.stroke();
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.4;
ctx.beginPath();
var ch = Math.min(26, H * 0.15);
for (var q = 0; q <= 200; q++) {
  var u = q / 200;
  var px = left + span * u;
  var py = cy - Math.sin(n * Math.PI * u) * ch * phase;
  if (q === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
}
ctx.stroke();
ctx.fillStyle = C.figure;
for (var i = 1; i <= N; i++) {
  var u2 = i / (N + 1);
  ctx.beginPath();
  ctx.arc(left + span * u2, cy - Math.sin(n * Math.PI * u2) * ch * phase, 3.5, 0, Math.PI * 2);
  ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("mode shape: a sine pinned to zero at both walls", left, cy + ch + 18);
ctx.fillText("bead displacements, k = 200 N/m, m = 0.50 kg", left, y - 34);

out.note = "N = " + N + ", mode n = " + n + ", omega = " + w.toFixed(1) +
  " rad/s  (2 sqrt(k/m) = " + (2 * Math.sqrt(k / m)).toFixed(1) + " rad/s)";
